"""Test block DataTable (Data): A table of many similar records with sortable columns, row selection, a row action and pages of 20.

Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/data/DataTable.md and its markup
(kit/blocks/data/DataTable.html; source 74ab159532e1), with the vocabulary in
functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.

Steps (e2e):
  Then the table shows {n} rows
  Then row {n} shows {text}
  When I sort by {column}
  Then the column {column} is sorted {direction}
  When I select the row {name}
  Then the row {name} is selected
  When I select all rows on this page
  When I open the actions for {name}
  When I go to page {n}
  When I go to the next page
  When I go to the previous page
  Then page {n} is the current page
  Then the table is in the {state} state
States (from the card): Default, Sorted, Row selected, All selected, Loading a page, Empty, Error, First / last
page, Many pages, Rows selected. Checked by the state step: Default, Row selected, Loading a page, Empty.
"""
from __future__ import annotations

from functional import Registry
from functional import primitives as p

BLOCK = "DataTable"
ROUTE = "/words?sort=added&dir=desc&page=1"
STATES = ["Default", "Sorted", "Row selected", "All selected", "Loading a page", "Empty", "Error", "First / last page", "Many pages", "Rows selected"]
DEFAULT_STATE = "Default"
CHECKED_STATES = ["Default", "Row selected", "Loading a page", "Empty"]
DEMO = ["kit/blocks/data/DataTable.html"]
SELF_TEST = [
    "Then the table shows 2 rows",
    "Then row 1 shows \"駅\"",
    "Then row 2 shows \"train\"",
    "Then the column \"Added\" is sorted descending",
    "Then the table is in the \"Default\" state",
    "When I select the row \"駅\"",
    "Then the row \"駅\" is selected",
    "Then page 1 is the current page",
    "When I go to page 2",
    "Then the table shows 2 rows",
]

steps = Registry(block=BLOCK)


class DataTable:
    """The DataTable block on a page: its controls, found as a person finds them (role and name, label, text)."""

    def __init__(self, page, base_url: str = ""):
        self.page = page
        self.base_url = base_url

    def form(self):
        return p.control(self.page, css="form:has(table)", block=BLOCK)

    def table(self):
        return p.control(self.page, role="table", block=BLOCK)

    def table_all(self):
        """Every match, possibly none (for counting)."""
        return self.page.get_by_role("table")

    def rows(self):
        return p.control(self.table(), css="tbody tr", block=BLOCK)

    def rows_all(self):
        """Every match, possibly none (for counting)."""
        return self.table().locator("tbody tr")

    def row(self, n):
        return p.control(self.table(), css="tbody tr", block=BLOCK).nth(int(n) - 1)

    def selected_row(self):
        return p.control(self.table(), css="tbody tr[data-state=\"selected\"]", block=BLOCK)

    def column(self, column):
        return p.control(self.table(), role="columnheader", name=str(column), block=BLOCK)

    def sort(self, column):
        return p.control(self.table(), role="button", name=f"Sort by {column}", block=BLOCK)

    def select_all(self):
        return p.control(self.table(), role="checkbox", name="Select all on this page", block=BLOCK)

    def select_row(self, name):
        return p.control(self.table(), role="checkbox", name=f"Select {name}", exact=True, block=BLOCK)

    def row_actions(self, name):
        return p.control(self.table(), role="link", name=f"Actions for {name}", exact=True, block=BLOCK)

    def pages(self):
        return p.control(self.page, role="navigation", name="Pages", block=BLOCK)

    def page_link(self, n):
        return p.control(self.pages(), role="link", name=f"Page {n}", exact=True, block=BLOCK)

    def previous(self):
        return p.control(self.pages(), role="link", name="Previous", block=BLOCK)

    def next(self):
        return p.control(self.pages(), role="link", name="Next", block=BLOCK)

    def expect_state(self, state: str) -> None:
        """Check one of the card's states: Default, Row selected, Loading a page, Empty."""
        b = self
        if state == "Default":
            p.expect_visible(b.rows().first)
        elif state == "Row selected":
            p.expect_visible(b.selected_row().first)
        elif state == "Loading a page":
            p.expect_attribute(b.form(), "aria-busy", "true")
        elif state == "Empty":
            p.expect_count(b.table_all(), 0)
        else:
            raise AssertionError(f"DataTable has no check for the state {state!r}; checked: " + ", ".join(CHECKED_STATES))


@steps.step("Then the table shows {n} rows", level="e2e")
def then_the_table_shows_n_rows(world, n):
    b = DataTable(world.page, getattr(world, "base_url", ""))
    p.expect_count(b.rows_all(), int(n))


